mapper.update:
update s_operation o join s_session s on s.id=o.session_id and s.active_turn_id=o.turn_id
set o.tts_dispatch_state='PREPARED',o.tts_owner=#{owner},o.tts_deadline_at=#{deadline}
where o.turn_id=#{turn} and o.ordinal=#{ordinal} and o.operation_type='TTS'
  and o.account_id=#{account} and o.session_id=#{session} and o.status='QUEUED'
  and o.tts_dispatch_state='NONE' and s.status='ACTIVE' and s.expires_at > utc_timestamp(3)
  and s.connection_epoch=#{epoch} and json_unquote(json_extract(o.result_summary,'$.segmentId'))=#{segment}

update s_operation o join s_session s on s.id=o.session_id and s.active_turn_id=o.turn_id
set o.tts_dispatch_state='DISPATCHING'
where o.turn_id=#{turn} and o.ordinal=#{ordinal} and o.operation_type='TTS' and o.tts_owner=#{owner}
  and o.tts_dispatch_state='PREPARED' and o.status='RUNNING' and o.settlement_status='NONE'
  and o.tts_deadline_at > utc_timestamp(3) and s.status='ACTIVE'
  and s.expires_at > utc_timestamp(3) and s.connection_epoch=#{epoch}
